import math

ACTIVATION_X_MIN = 5.0
ACTIVATION_X_MAX = 10.0
BACKWARD_FX_THRESHOLD = -34.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
MAX_STRUCTURAL_IMPULSE = 250.0

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "vx": 0.0,
            "vy": 0.0,
            "lx": None,
            "ly": None,
            "unlock_streak": 0,
        }
    state = MEM.data["initial_state"]

    pd = sandbox.get_agent_position()
    vx_p, vy_p = sandbox.get_agent_velocity()
    x, y = pd[0], pd[1]

    if state["lx"] is not None:
        state["vx"] = (x - state["lx"]) / TIME_STEP
        state["vy"] = (y - state["ly"]) / TIME_STEP
    state["lx"], state["ly"] = x, y

    front, up, down = sandbox.get_whisker_readings()
    w_comp = 5.0 * sandbox.world.gravity[1]  # Mass * gravity

    if state["phase"] == "APPROACH":
        target_y = 1.6  # Below wall #4 top at 1.7 m
        Kp_y = 30.0
        Kv_y = 10.0
        fy = Kp_y * (target_y - y) - Kv_y * vy_p + w_comp

        # Forward thrust: High in open space, reduced near walls
        if front < 0.5:
            fx = 100.0 + 0.5 * (0.5 - state["vx"])
        else:
            fx = 200.0 + 0.5 * (1.0 - state["vx"])

        # Transition to UNLOCK when inside activation zone and moving forward
        if x >= ACTIVATION_X_MIN - 0.2 and x < ACTIVATION_X_MAX and state["vx"] > 0:
            state["phase"] = "UNLOCK"
            state["t"] = 0
            state["unlock_streak"] = 0

    elif state["phase"] == "UNLOCK":
        fx = -35.0  # Satisfy unlock condition
        target_y = 1.6
        fy = 30.0 * (target_y - y) - 10.0 * vy_p + w_comp

        # Track unlock condition
        if x >= ACTIVATION_X_MIN and x <= ACTIVATION_X_MAX and fx < BACKWARD_FX_THRESHOLD and math.hypot(vx_p, vy_p) < 100.0:
            state["unlock_streak"] += 1
        else:
            state["unlock_streak"] = 0

        if state["unlock_streak"] >= 5:
            state["phase"] = "ESCAPE"

    elif state["phase"] == "ESCAPE":
        fx = 15.0  # Moderate thrust to reach exit
        target_y = 1.6
        fy = 30.0 * (target_y - y) - 10.0 * vy_p + w_comp
        if x > EXIT_X_MIN:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp  # Hold in place

    sandbox.apply_agent_force(fx, fy)

