    elif state["phase"] == "ESCAPE":
        # Forward force to reach exit
        fx = 150.0

        # Vertical PD to maintain clearance
        if up < 0.4:
            target_y = 1.8
        elif down < 0.4:
            target_y = 2.2
        else:
            target_y = 1.5
        Kp_y, Kv_y = 50.0, 20.0
        fy = Kp_y * (target_y - y) - Kv_y * vy_p + w_comp

        # Transition to HOLD once in exit zone
        if x >= EXIT_X_MIN:
            state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        # Maintain position in exit zone
        fx, fy = 0.0, w_comp

    sandbox.apply_agent_force(fx, fy)
